function resultDialog(){let r=game.s.result;openModal(`<img src="ritual.png" alt="降魂仪式概念图"><div class="eyebrow">THE NIGHT ENDS</div><h2 class="result-title">${r.team==='hero'?'英雄生还':'小屋吞噬了一切'}</h2><p>${esc(r.reason)}</p><p><strong>获胜阵营：${r.team==='hero'?'英雄':'叛徒'}</strong><br>${game.s.players.filter(p=>p.team===r.team).map(p=>esc(p.name)+(p.alive?'':'（已倒下）')).join('、')}</p><p>英雄仪式 ${game.s.heroProgress}/3 · 叛徒仪式 ${game.s.traitorProgress}/3${game.s.ghost?' · 驱散 '+game.s.ghost.hits+'/3':''}</p><p>历经 ${r.round} 轮 · ${game.s.rooms.length} 间房 · ${game.s.omen} 个预兆</p><div class="dialogactions">${btn('查看棋局','close')}${btn('导出日志','export')}${btn('新对局','new',false,'primary')}</div>`,false)}
function afterAction(before,wasAI=false){
 const s=game.s;
 const guide=guideState();
 const firstOmen=guide.enabled&&!guide.omenExplained&&s.report?.title.startsWith('预兆 ·');
 if(guide.enabled&&s.lastHauntCheck&&s.lastHauntCheck.serial!==(guide.seenCheck||0)){
  guide.seenCheck=s.lastHauntCheck.serial;
  if(s.phase==='explore'&&!guide.explained?.['作祟检定'])s.report={title:'作祟检定',text:'本回合的预兆已完成检定。下面解释这次骰子结果意味着什么。'};
 }
 if(wasAI&&!firstOmen&&s.report&&!['降魂仪式','幽灵回应了英雄','幽灵回应了叛徒','作祟检定'].includes(s.report.title)){
  game.log('AI · '+s.report.title+'：'+s.report.text);s.report=null;
 }
 pendingHandoff=s.mode==='local'&&!game.isAI()&&before!==s.active&&!s.result;
 floor=game.roomNow.f;persist();render();
 if(s.report&&!s.result)report();else if(pendingHandoff)handoff();
 scheduleAI();
}
function scheduleAI(){
 clearTimeout(aiTimer);
 if(game&&!modal.open&&!game.s.result&&game.isAI()){
  const expectedGame=game,active=game.s.active;
  aiTimer=setTimeout(()=>{
   if(game!==expectedGame||modal.open||game.s.active!==active||!game.isAI())return;
   game.aiStep();afterAction(active,true);
  },650);
 }
}
